defmodule Oneiroi.Repo.Migrations.AddEventStore do
  use Ecto.Migration

  # The event log's own schema (conventions §6, §12): a dedicated
  # Postgres schema whose DDL is generated by the pinned `eventstore`
  # dependency itself, so the store's tables stay in lockstep with the
  # adapter that runs them, under the one migration runner the Repo's
  # tables use. Reached only through `Oneiroi.EventStore` and Commanded.
  @schema "eventstore"

  def up do
    execute(~s(CREATE SCHEMA "#{@schema}"))

    # The types are the library's own defaults, spelled here because the
    # generator takes no defaults; `Oneiroi.EventStore.init/1` names the
    # same column type so the schema and the store cannot disagree.
    config = [schema: @schema, column_data_type: "jsonb", correlation_id_type: "uuid", causation_id_type: "uuid"]

    for statement <- EventStore.Sql.Init.statements(config) do
      execute(statement)
    end

    # The first statement above is `SET LOCAL search_path`, which lives
    # for the rest of this migration's transaction and would otherwise
    # point Ecto's own version row at the store's table of the same name.
    execute(~s(SET LOCAL search_path TO "public";))
  end

  def down do
    execute(~s(DROP SCHEMA "#{@schema}" CASCADE))
  end
end
